class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def isCompleteBT(root):
    from collections import deque
    if not root:
        return True
    queue = deque([root])
    end = False
    while queue:
        node = queue.popleft()
        if node.left:
            if end:
                return False
            queue.append(node.left)
        else:
            end = True
        if node.right:
            if end:
                return False
            queue.append(node.right)
        else:
            end = True
    return True
